import { Component, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import {
  TablerIconComponent, IconMail, IconLock, IconEye, IconEyeOff, IconUser, IconWorld, IconChevronDown,
} from '@tabler/icons-angular';
import { HrmInput, HrmButton, HrmCheckbox, HrmDivider } from 'hrm-ui';

/** Trang đăng nhập — mẫu (Template). Nền xanh VnResource full trang, thẻ đăng nhập bên phải,
 *  lời chứng thực bên trái. Branding xanh lá từ logo (#145300 / #8EC517). Dùng component + token DS. */
@Component({
  selector: 'app-login',
  imports: [FormsModule, TranslateModule, TablerIconComponent, HrmInput, HrmButton, HrmCheckbox, HrmDivider],
  template: `
    <div class="lg">
      <!-- Trái: chứng thực (trên nền xanh) -->
      <aside class="lg-brand">
        <div class="lg-quote">
          <p class="lg-q-text">{{ 'docs.login.quote' | translate }}</p>
          <div class="lg-q-name">Nguyễn Trung Hiếu</div>
          <div class="lg-q-role">{{ 'docs.login.quoteRole' | translate }}</div>
          <div class="lg-dots"><i class="on"></i><i></i><i></i></div>
        </div>
      </aside>

      <!-- Phải: thẻ đăng nhập -->
      <section class="lg-form">
        <header class="lg-top">
          <img class="lg-logo-img" src="/assets/vnr-wordmark.svg" alt="VnResource" />
          <span class="lg-reg">{{ 'docs.login.noAccount' | translate }} <button type="button" class="lg-reg-btn">{{ 'docs.login.register' | translate }}</button></span>
        </header>

        <div class="lg-card">
          <div class="lg-avatar"><tabler-icon [icon]="userIc" [size]="26" /></div>
          <h1 class="lg-title">{{ 'docs.login.title' | translate }}</h1>
          <p class="lg-sub">{{ 'docs.login.subtitle' | translate }}</p>

          <div class="lg-social">
            <hrm-button [block]="true" variant="default" [ariaLabel]="'docs.login.ssoWith' | translate:{ provider: 'Google' }">
              <svg width="20" height="20" viewBox="0 0 48 48" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                <path fill="#FFC107" d="M43.6 20.5H42V20H24v8h11.3c-1.6 4.7-6.1 8-11.3 8-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.3-.4-3.5z"/>
                <path fill="#FF3D00" d="M6.3 14.7l6.6 4.8C14.6 15.1 18.9 12 24 12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 16.3 4 9.7 8.3 6.3 14.7z"/>
                <path fill="#4CAF50" d="M24 44c5.2 0 9.9-2 13.4-5.2l-6.2-5.2c-2 1.5-4.6 2.4-7.2 2.4-5.2 0-9.6-3.3-11.3-7.9l-6.5 5C9.6 39.6 16.2 44 24 44z"/>
                <path fill="#1976D2" d="M43.6 20.5H42V20H24v8h11.3c-.8 2.3-2.2 4.3-4.1 5.6l6.2 5.2C40.9 35.7 44 30.4 44 24c0-1.3-.1-2.3-.4-3.5z"/>
              </svg>
            </hrm-button>
            <hrm-button [block]="true" variant="default" [ariaLabel]="'docs.login.ssoWith' | translate:{ provider: 'Microsoft' }">
              <svg width="18" height="18" viewBox="0 0 23 23" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                <path fill="#F25022" d="M1 1h10v10H1z"/><path fill="#7FBA00" d="M12 1h10v10H12z"/>
                <path fill="#00A4EF" d="M1 12h10v10H1z"/><path fill="#FFB900" d="M12 12h10v10H12z"/>
              </svg>
            </hrm-button>
            <hrm-button [block]="true" variant="default" [ariaLabel]="'docs.login.ssoWith' | translate:{ provider: 'LinkedIn' }">
              <svg width="20" height="20" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                <path fill="#0A66C2" d="M20.45 20.45h-3.56v-5.57c0-1.33-.02-3.04-1.85-3.04-1.85 0-2.14 1.45-2.14 2.94v5.67H9.35V9h3.42v1.56h.05c.48-.9 1.64-1.85 3.37-1.85 3.6 0 4.27 2.37 4.27 5.46v6.28zM5.34 7.43a2.06 2.06 0 1 1 0-4.13 2.06 2.06 0 0 1 0 4.13zM7.12 20.45H3.56V9h3.56v11.45zM22.22 0H1.77C.8 0 0 .78 0 1.74v20.5C0 23.2.8 24 1.77 24h20.45c.98 0 1.78-.8 1.78-1.76V1.74C24 .78 23.2 0 22.22 0z"/>
              </svg>
            </hrm-button>
          </div>

          <hrm-divider [text]="'docs.login.or' | translate" />

          <label class="lg-field">
            <span class="lg-label">Email</span>
            <hrm-input [(ngModel)]="email" [prefixIcon]="mail" htmlType="email" placeholder="hello@vnresource.com" />
          </label>

          <label class="lg-field">
            <span class="lg-label">{{ 'docs.login.password' | translate }}</span>
            <span class="lg-pass">
              <hrm-input [(ngModel)]="password" [prefixIcon]="lock" [htmlType]="show() ? 'text' : 'password'" placeholder="••••••••••" />
              <button type="button" class="lg-eye" (click)="show.set(!show())" [attr.aria-label]="(show() ? 'docs.login.hidePassword' : 'docs.login.showPassword') | translate">
                <tabler-icon [icon]="show() ? eyeOff : eye" [size]="18" />
              </button>
            </span>
          </label>

          <div class="lg-row">
            <hrm-checkbox [(ngModel)]="remember">{{ 'docs.login.remember' | translate }}</hrm-checkbox>
            <button type="button" class="lg-forgot">{{ 'docs.login.forgot' | translate }}</button>
          </div>

          <hrm-button variant="primary" [block]="true" class="lg-submit">{{ 'docs.login.signIn' | translate }}</hrm-button>
        </div>

        <footer class="lg-foot">
          <span>© 2025 VnResource</span>
          <button type="button" class="lg-lang"><tabler-icon [icon]="world" [size]="16" /> {{ 'docs.login.lang' | translate }} <tabler-icon [icon]="chev" [size]="14" /></button>
        </footer>
      </section>
    </div>
  `,
  styles: [`
    :host {
      /* Branding xanh lá VnResource — nền gradient FULL trang. primary = xanh → hrm component tự bám. */
      --vnr-dark: #145300; --vnr-green: #1c7a0a; --vnr-lime: #8ec517;
      --primary-base: #1c7a0a;
      position: relative; display: block; height: 100vh; overflow: hidden; isolation: isolate;
      font-family: var(--font-sans); color: var(--text-body);
      background: linear-gradient(158deg, #0f4d00 0%, #256b0e 46%, #7fbf1f 100%);
    }
    /* Vòng tròn đồng tâm mờ trên nền xanh. */
    :host::before {
      content: ''; position: absolute; left: -160px; top: -160px; width: 720px; height: 720px; z-index: -1;
      border-radius: 50%; pointer-events: none;
      background: repeating-radial-gradient(circle at center, transparent 0 46px, rgba(255,255,255,.06) 46px 48px);
    }
    /* Thẻ đăng nhập (phải) : nền (trái) = 1.5 : 1 (form rộng hơn, gọn hơn tỉ lệ vàng). */
    .lg { display: grid; grid-template-columns: 1fr 1.5fr; height: 100vh; padding: 24px; gap: 24px; box-sizing: border-box; }

    /* ---- Trái: thương hiệu trên nền xanh ---- */
    .lg-brand { flex: 1; min-width: 0; color: #fff; display: flex; flex-direction: column; justify-content: flex-end; padding: 30px 26px; }
    .lg-logo { display: inline-flex; align-items: center; gap: 10px; }
    .lg-logo b { font-size: var(--fs-19); font-weight: 700; color: #fff; letter-spacing: -.01em; }
    .lg-quote { max-width: 540px; }
    .lg-q-text { font-size: var(--fs-26); line-height: 1.44; font-weight: 500; margin: 0 0 24px; }
    .lg-q-name { font-size: var(--fs-16); font-weight: 700; }
    .lg-q-role { font-size: var(--fs-14); color: rgba(255,255,255,.82); margin-top: 3px; }
    .lg-dots { display: flex; gap: 7px; margin-top: 24px; }
    .lg-dots i { width: 8px; height: 8px; border-radius: 50%; background: rgba(255,255,255,.4); }
    .lg-dots i.on { width: 22px; border-radius: 5px; background: #fff; }

    /* ---- Phải: thẻ đăng nhập ---- */
    .lg-form {
      min-width: 0; background: var(--bg-surface); border-radius: 26px;
      padding: 30px 46px; display: flex; flex-direction: column; box-shadow: 0 20px 60px rgba(0,0,0,.18);
    }
    .lg-top { display: flex; align-items: center; justify-content: space-between; min-height: 40px; gap: 16px; }
    .lg-logo-img { height: 32px; width: auto; display: block; }
    .lg-reg { font-size: var(--fs-14); color: var(--text-sub); display: inline-flex; align-items: center; gap: 10px; white-space: nowrap; }
    /* Nút Đăng ký — chip nền tint (như cũ) nhưng màu tươi hơn (lime + chữ xanh sáng). */
    .lg-reg-btn { border: 0; cursor: pointer; font-weight: 600; color: #2f9e0e;
      background: color-mix(in srgb, var(--vnr-lime) 22%, transparent); padding: 6px 14px; border-radius: 10px; font-size: var(--fs-14);
      transition: background .15s; }
    .lg-reg-btn:hover { background: color-mix(in srgb, var(--vnr-lime) 34%, transparent); }

    .lg-card { flex: 1; display: flex; flex-direction: column; align-items: stretch; width: 100%; max-width: 372px; margin: 0 auto; justify-content: center; }
    .lg-avatar {
      width: 64px; height: 64px; border-radius: 50%; display: grid; place-items: center; margin: 0 auto 16px;
      color: var(--vnr-green); background: var(--bg-surface);
      box-shadow: 0 0 0 1px var(--border-sub), 0 0 0 8px color-mix(in srgb, var(--vnr-lime) 16%, transparent);
    }
    .lg-title { font-size: var(--fs-26); font-weight: 700; color: var(--text-strong); text-align: center; margin: 0; }
    .lg-sub { font-size: var(--fs-14); color: var(--text-sub); text-align: center; margin: 6px 0 22px; }

    .lg-social { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
    .lg-social hrm-button ::ng-deep .ant-btn { height: 46px; }

    /* Divider "Hoặc" — dùng hrm-divider; chữ nhỏ + màu phụ. */
    .lg-card hrm-divider { display: block; margin: 18px 0; }
    .lg-card hrm-divider ::ng-deep .ant-divider-inner-text { font-size: var(--fs-12); color: var(--text-sub); font-weight: 500; }

    .lg-flag { font-size: var(--fs-15); line-height: 1; }

    .lg-field { display: block; margin-bottom: 16px; }
    .lg-label { display: block; font-size: var(--fs-14); font-weight: 500; color: var(--text-strong); margin-bottom: 7px; }
    .lg-label i { color: var(--vnr-lime); font-style: normal; }
    .lg-field hrm-input { display: block; width: 100%; }

    .lg-pass { position: relative; display: block; }
    .lg-eye { position: absolute; right: 12px; top: 50%; transform: translateY(-50%); z-index: 2;
      border: 0; background: transparent; cursor: pointer; color: var(--text-sub); display: inline-flex; }
    .lg-eye:hover { color: var(--text-strong); }

    .lg-row { display: flex; align-items: center; justify-content: space-between; margin: 6px 0 22px; }
    .lg-forgot { border: 0; background: transparent; cursor: pointer; font-size: var(--fs-14); font-weight: 600; color: var(--vnr-green); }
    .lg-forgot:hover { text-decoration: underline; }

    .lg-foot { display: flex; align-items: center; justify-content: space-between; font-size: var(--fs-13); color: var(--text-sub); }
    .lg-lang { border: 0; background: transparent; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; color: var(--text-sub); font-size: var(--fs-13); }

    @media (max-width: 900px) { .lg-brand { display: none; } .lg-form { width: 100%; } }
  `],
})
export class LoginPage {
  protected readonly userIc = IconUser;
  protected readonly mail = IconMail;
  protected readonly lock = IconLock;
  protected readonly eye = IconEye;
  protected readonly eyeOff = IconEyeOff;
  protected readonly world = IconWorld;
  protected readonly chev = IconChevronDown;

  protected email = '';
  protected password = '';
  protected remember = true;
  protected readonly show = signal(false);
}
